head.script:
scwin.displayFormatter = function(value) {
    //debugger;
    log = this.callerId;
    //alert(this.callerId);
    return '[' + value + ']';
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 inputbox에 값('111')을 입력하고 마우스를 focus out 시킨다.
    //1. After executing the sample, enter the value ('111') in the input box and focus out the mouse.
    //Verify step 1. The 'wq_uuid_1' value is displayed in the notification window.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#wq_uuid_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1').setValue('111')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log == $p.id+'wq_uuid_1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 23-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
